class MinQueue:
    def __init__(self):
        self.in_st, self.out_st = [], []   # (value, running_min) pairs
    def push(self, v):
        mn = min(v, self.in_st[-1][1]) if self.in_st else v
        self.in_st.append((v, mn))
    def _shift(self):
        if not self.out_st:
            while self.in_st:
                v, m = self.in_st.pop()
                mn = min(m, self.out_st[-1][1]) if self.out_st else v
                self.out_st.append((v, mn))
    def pop(self):
        self._shift(); return self.out_st.pop()[0]
    def min(self):
        candidates = [s[-1][1] for s in (self.in_st, self.out_st) if s]
        return min(candidates)
